"""42 original literal finding articles; no source changes or generated substitute copy."""
from pathlib import Path
import re
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';j=(r/'docs/replica/source/original.js').read_text()
start=j.index('function findings()');end=j.index('function categoryVerdict(',start);findings=j[start:end]
t=next(x for x in j.splitlines() if x.startswith('const t='))
markup=re.search(r'\.map\(f=>`(<article class="finding">.*?</article>)`\)',j).group(1)
script="let lang='ko';let state={run:null};"+t+'\n'+findings+'''
const cases=[];for(const english of [false,true])for(const width of [326,656,904])for(const kind of ['data','schema','objects','map','unknown','interrupted','pending']){
 lang=english?'en':'ko';let g={key:kind==='map'?'schema':kind==='unknown'?'access':kind==='interrupted'||kind==='pending'?'data':kind,status:kind==='interrupted'?'interrupted':kind==='pending'?'pending':'completed',total:12,done:kind==='interrupted'?5:kind==='pending'?0:12,different:['data','schema','objects'].includes(kind)?1:0,unknown:kind==='unknown'?2:0};state.run={groups:[g],tableNames:['demo.orders'],maps:kind==='map'?{'demo.orders':'demo.orders_v2'}:{}};
 const f=findings()[0];const holder=document.createElement('div');holder.style.width=width+'px';holder.className='fixture';holder.innerHTML=`'''+markup+'''`;const id=`${english?'en':'ko'}-${width}-${kind}`;holder.dataset.id=id;document.querySelector('#fixtures').append(holder);cases.push({...f,findingId:f.id,id,english,width});
}
function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const root=f.firstChild,r=root.getBoundingClientRect();const box=n=>{const b=n.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}};const top=root.children[0],location=root.children[1],reason=root.children[2];const marker=document.createElement('span');marker.style.cssText='display:inline-block;width:0;height:0';location.append(marker);const baseline=marker.getBoundingClientRect().y-location.getBoundingClientRect().y;marker.remove();return{id:f.dataset.id,root:box(root),top:box(top),title:box(top.children[0]),identifier:box(top.children[1]),location:box(location),locationInline:box(location.children[0]),locationBaseline:baseline,reason:box(reason),titleText:top.children[0].textContent,identifierText:top.children[1].textContent,locationText:location.textContent,reasonText:reason.textContent,css:Object.fromEntries(['backgroundColor','borderColor','borderWidth','borderRadius','padding','animationName','animationDuration'].map(k=>[k,getComputedStyle(root)[k]]))}})}
'''
(o/'findingarticle-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'findingarticle-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="findingarticle-original.css"><style>.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden}.finding{animation:none!important}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'findingarticle.html').write_text('''<!doctype html><meta charset="utf-8"><title>FindingArticle · original isolation</title><button id="findingarticle-record">Record FindingArticle</button><iframe width="1000" height="600" src="findingarticle-inner.html"></iframe><script>document.querySelector('#findingarticle-record').onclick=async()=>{const f=document.querySelector('iframe');await f.contentDocument.fonts.ready;const data={dpr:devicePixelRatio,rows:f.contentWindow.read(),cases:f.contentWindow.cases};const result=await fetch('/evidence/connection-findingarticle-'+(new URLSearchParams(location.search).get('os')||'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!result.ok)throw Error('Record failed');document.querySelector('#findingarticle-record').textContent='FindingArticle recorded';}</script>'''.replace('f.contentWindow.cases','f.contentWindow.getCases()'))
# Expose only readonly fixture case accessor.
with (o/'findingarticle-inner.html').open('a')as f:f.write('<script>function getCases(){return cases}</script>')
print('42 literal articles prepared')
(o/'findingarticle-lifecycle.html').write_text('''<!doctype html><meta charset="utf-8"><title>FindingArticle lifecycle · original isolation</title><link rel="stylesheet" href="findingarticle-original.css"><style>#owned{width:904px;margin:30px}.findingarticle-reduced{animation:none!important}</style><button id="findingarticle-run">Run FindingArticle lifecycle</button><iframe src="findingarticle-inner.html" hidden></iframe><div id="owned"></div><script>document.querySelector('#findingarticle-run').onclick=async()=>{const frame=document.querySelector('iframe');await frame.contentDocument.fonts.ready;const article=[...frame.contentDocument.querySelectorAll('article.finding')].at(-1).cloneNode(true),holder=document.querySelector('#owned'),title=article.querySelector('strong'),location=article.children[1].firstChild,rows=[];function state(label){const style=getComputedStyle(article);rows.push({label,attached:article.isConnected,opacity:article.isConnected?Number(style.opacity):null,y:article.isConnected?new DOMMatrix(style.transform).m42:null,sameTitle:title===article.querySelector('strong'),sameLocation:location===article.children[1].firstChild,focusable:article.tabIndex>=0})}holder.append(article);state('normal-start');await new Promise(r=>setTimeout(r,260));state('normal-end');article.remove();state('detached');holder.append(article);state('reattached');await new Promise(r=>setTimeout(r,260));state('reattached-end');article.classList.add('findingarticle-reduced');state('reduced');const result=await fetch('/evidence/connection-findingarticle-'+(new URLSearchParams(location.search).get('os')||'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!result.ok)throw Error('Record failed');document.querySelector('#findingarticle-run').textContent='FindingArticle lifecycle recorded';}</script>'''.replace("location=article.children[1].firstChild","locationNode=article.children[1].firstChild").replace("sameLocation:location===","sameLocation:locationNode==="))
